from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parent.parent
BASE='https://tripvanda.com'
def wa(message): return 'https://wa.me/918129422113?text='+__import__('urllib.parse',fromlist=['quote']).quote(message)
def button(text='Plan my trip',message='Hi Tripvanda! I would like to plan a trip.',cls='btn primary'): return f'<a class="{cls}" href="{wa(message)}" target="_blank" rel="noopener noreferrer">{text} <span aria-hidden="true">↗</span></a>'
photos={'hero':'photo-1512343879784-a960bf40e7f2','kerala':'photo-1602216056096-3b40cc0c9944','bali':'photo-1537996194471-e657df975ab4','maldives':'photo-1514282401047-d79a71a590e8','mountains':'photo-1464822759023-fed622ff2c3b'}
def photo(key): return 'https://images.unsplash.com/'+photos[key]+'?auto=format&fit=crop&w=1000&q=80'
def image(key,alt,cls=''): return f'<img class="{cls}" src="{photo(key)}" alt="{alt}" loading="lazy" width="1000" height="750">'
nav=[('index.html','Home'),('services.html','Our services'),('destinations.html','Destinations'),('about.html','About us'),('contact.html','Contact')]
def cards():
 return ''.join(f'<a class="destination" href="destinations.html#{key}">{image(key,alt)}<span class="destination-label"><small>{tag}</small><strong>{name}</strong><span>Find your inspiration ↗</span></span></a>' for key,name,tag,alt in [('kerala','Kerala','SLOW DOWN & SOAK IT IN','Palm trees and tranquil Kerala backwaters'),('bali','Bali','A LITTLE ISLAND MAGIC','Lush tropical landscape and architecture in Bali'),('maldives','Maldives','YOUR BLUE-SKY ESCAPE','Turquoise lagoon and island in the Maldives')])
def service_cards():
 return ''.join(f'<a class="service-card" href="{slug}.html"><span class="service-icon" aria-hidden="true">{icon}</span><h3>{name}</h3><p>{desc}</p><span class="text-link">Explore service ↗</span></a>' for slug,icon,name,desc in [('taxi-services','↗','Taxi services','Airport runs, a day out, or a longer road trip. Tell us where you’re headed.'),('flight-tickets','✈','Flight tickets','Share your route and travel dates. Let’s explore flight options together.'),('train-tickets','⇄','Train tickets','Get help with routes, classes and ticket enquiries for your next rail journey.')])
def faq(items): return '<div class="faqs">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in items)+'</div>'
def intro(kicker,title,desc): return f'<section class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></section>'
def cta(): return '<section class="cta wrap"><div><p class="eyebrow">GOOD JOURNEYS START WITH A CONVERSATION</p><h2>Where shall we go next?</h2><p>A destination in mind? A question about getting there? Let’s talk.</p></div>'+button('Let’s talk on WhatsApp')+'</section>'
home=f'''<section class="hero"><img class="hero-image" src="{photo('hero')}" alt="Sunlit palm-lined coast in Goa, India" width="1800" height="1200" fetchpriority="high"><div class="hero-shade"></div><div class="hero-content wrap"><p class="eyebrow light"><span></span> EXPLORE · EXPERIENCE · TOGETHER</p><h1>Go somewhere<br>you’ll <em>never forget.</em></h1><p>From the first mile to the window seat.<br>Your next journey starts with Tripvanda.</p><div class="hero-actions">{button('Let’s plan your journey')}<a class="btn glass" href="destinations.html">Explore destinations <span>↗</span></a></div><div class="hero-bottom"><span>LESS PLANNING. MORE LIVING.</span><span>Discover the extraordinary ↓</span></div></div><div class="place-tag">◎ &nbsp; A little closer to paradise<br><small>Goa, India</small></div></section>
<section class="enquiry-bar wrap" aria-label="Start a travel enquiry"><div><span class="small-label">YOUR NEXT CHAPTER</span><h2>What’s your travel plan?</h2></div><form action="https://wa.me/918129422113" method="get" data-quick-form><label>I’m looking for<select name="service"><option>Taxi services</option><option>Flight tickets</option><option>Train tickets</option><option>Travel planning</option></select></label><label>Where to?<input name="destination" placeholder="Your destination" required maxlength="120"></label><button class="btn primary" type="submit">Let’s go <span>↗</span></button><input type="hidden" name="text" value="Hi Tripvanda! I would like help planning my journey."></form></section>
<section class="section wrap"><div class="section-heading"><div><p class="eyebrow">THE WORLD IS CALLING</p><h2>A change of scenery.<br>A whole new feeling.</h2></div><div><p>Find a little inspiration for your next escape.<br>We’ll help you work out the journey.</p><a class="text-link" href="destinations.html">Explore destinations ↗</a></div></div><div class="destination-grid">{cards()}</div><p class="caption">Places to inspire your plans. Travel arrangements and availability are confirmed individually.</p></section>
<section class="services-section"><div class="wrap section"><div class="section-heading"><div><p class="eyebrow">EVERY LEG OF YOUR JOURNEY</p><h2>You dream it.<br>Let’s get you there.</h2></div><p>On the road, above the clouds, or along the rails.<br>One friendly conversation to get started.</p></div><div class="service-grid">{service_cards()}</div></div></section>
<section class="section wrap story"><div class="story-image">{image('kerala','A quiet stretch of Kerala’s palm-lined backwaters')}<span class="image-note">Take the scenic route.</span></div><div><p class="eyebrow">A PERSONAL TOUCH, EVERY STEP</p><h2>Real people.<br>Thoughtful journeys.</h2><p class="lead">Travel feels better when you have someone to talk to.</p><p>At Tripvanda, we bring taxi services and flight and train ticket assistance together. Share your plans, ask your questions, and work through the details with us on WhatsApp.</p><ul class="check-list"><li>Your plans, your pace</li><li>One contact for your travel enquiries</li><li>Details discussed before you commit</li></ul><a href="about.html" class="text-link">Meet Tripvanda ↗</a></div></section>
<section class="section wrap faq-section"><div><p class="eyebrow">A FEW THINGS TO KNOW</p><h2>Before you<br>pack your bags.</h2></div>{faq([('How do I enquire about a journey?','Use any WhatsApp button, share your travel dates and destination, and our team will discuss the next steps. You can also call +91 81294 22113.'),('Can I book or pay on this website?','This website is for information and enquiries. There is no online checkout or instant booking. All details are discussed directly with Tripvanda.'),('Can you help with taxis, flights and trains?','Yes. We accept enquiries for taxi services, flight ticket booking assistance and train ticket booking assistance. Options depend on your route, dates and availability.'),('Are prices and availability guaranteed?','No. Fares and availability can change. Request a current quote and confirm inclusions, charges and cancellation conditions before proceeding.')])}</section>'''
pages={
'index.html':('Tripvanda | Taxi & Travel Services in Karunagappally, Kollam','Tripvanda, Karunagappally, Kollam: enquire about taxi services, flight tickets and train tickets. Plan your next journey on WhatsApp or call +91 81294 22113.',home),
'services.html':('Travel Services | Taxi, Flights & Trains | Tripvanda','Explore Tripvanda taxi services, flight ticket and train ticket assistance. Share your travel plans on WhatsApp for a personalised enquiry.',intro('THE JOURNEY, MADE PERSONAL','Every way to get away.','Three travel essentials. One conversation. Tell us what you need, and we’ll help you explore the options.')+f'<section class="wrap section"><div class="service-grid">{service_cards()}</div></section>'+intro('HOW IT WORKS','From an idea to a plan.','Share your route and dates. Discuss the available options and a current quote. Confirm the details directly with our team before making arrangements.').replace('<h1>', '<h2>').replace('</h1>', '</h2>')),
'about.html':('About Tripvanda | Explore, Experience, Together','Meet Tripvanda: taxi services and flight and train ticket assistance with a personal approach. Start a conversation about your next journey.',intro('HELLO, WE’RE TRIPVANDA','A world to explore.<br>Someone to help.','Explore. Experience. Together. That’s the spirit behind Tripvanda.')+f'<section class="wrap section story"><div class="story-image">{image("mountains","Mountain peaks inviting a new adventure")}</div><div><h2>Good travel starts<br>with good conversation.</h2><p class="lead">Your journey is personal. Planning it should feel that way too.</p><p>Based in Karunagappally, Kollam, Kerala, Tripvanda helps travellers with taxi enquiries, flight tickets and train tickets. We keep things direct: share your plans with us on WhatsApp or phone, ask questions, and discuss the options that fit your journey.</p><p>Whether you’re heading to the airport, travelling to see family, or thinking about a change of scenery, we’re here to help with the next step.</p>{button("Say hello")}</div></section>'),
'destinations.html':('Travel Inspiration & Destinations | Tripvanda','Explore Kerala, Bali and the Maldives as inspiration for your next journey. Ask Tripvanda about travel arrangements, flights and local transport.',intro('FOLLOW YOUR CURIOSITY','Where will your story go?','A few places to get your imagination moving. Share your destination and dates to ask about travel arrangements.')+f'<section class="wrap section"><div class="destination-grid">{cards()}</div></section>'+''.join(f'<section id="{key}" class="wrap destination-detail"><p class="eyebrow">DESTINATION INSPIRATION</p><h2>{name}</h2><p class="lead">{desc}</p><p>These are ideas for your itinerary, rather than a fixed package. Ask us which travel arrangements we can help with for your dates.</p>{button("Ask about "+name,"Hi Tripvanda! I’m interested in travelling to "+name+". Can you help with travel arrangements?")}</section>' for key,name,desc in [('kerala','Kerala','Palm-lined backwaters, green hills and unhurried coastal days. Think about a backwater stay, a hill-country drive or a beach break.'),('bali','Bali','Temple courtyards, rice terraces and island sunsets. Build your wish list around culture, coastlines and time to unwind.'),('maldives','Maldives','Clear lagoons, island mornings and time by the ocean. Start with your preferred dates and the kind of island stay you have in mind.')]))}
service_data=[('taxi-services','Taxi Services','Taxi services in<br>Karunagappally, Kollam.','Ask Tripvanda about airport transfers, local trips and outstation taxi journeys. Share your pickup location, destination and dates on WhatsApp.','A smooth start. A scenic detour. A ride home. Tell us about your journey and ask for a taxi quote.',['Airport pickup and drop enquiries','Local travel and day-trip enquiries','Outstation and multi-stop travel enquiries'],'Pickup location, destination, date, time, number of passengers and luggage.'),('flight-tickets','Flight Ticket Assistance','Your next window-seat moment.','Enquire about flight ticket booking assistance with Tripvanda. Share departure and arrival cities, travel dates and passenger count on WhatsApp.','A quick getaway or a long-awaited journey. Share your route and let’s discuss flight options.',['Flight route and fare enquiries','One-way and return journey enquiries','Questions about baggage and fare conditions'],'Departure and arrival airports, travel dates, passenger count and preferred cabin.'),('train-tickets','Train Ticket Assistance','Let the journey be part of the story.','Get train ticket booking assistance from Tripvanda. Enquire about routes, travel dates, classes and availability over WhatsApp.','Window views and the rhythm of the rails. Get help with your next train travel enquiry.',['Train route and class enquiries','Journey date and availability enquiries','Questions about ticket status and travel details'],'Departure and destination stations, date of travel, passenger count and preferred class.')]
for slug,name,title,desc,lead,items,needed in service_data:
 pages[slug+'.html']=(name+' | Tripvanda',desc,intro(name.upper(),title,lead)+f'<section class="wrap section service-detail"><div><h2>Let’s work out the details.</h2><ul class="check-list">'+''.join('<li>'+x+'</li>' for x in items)+f'</ul><h3>What to share</h3><p>{needed}</p>{button("Enquire on WhatsApp","Hi Tripvanda! I’d like help with "+name.lower()+".")}</div><aside class="info-panel"><p class="eyebrow">BEFORE YOU CONFIRM</p><h3>A clear quote comes first.</h3><p>Availability, fares and service coverage depend on your route and travel dates. Ask for the total charges, inclusions and cancellation conditions before confirming.</p><p>An enquiry does not reserve a vehicle, seat or ticket.</p><a class="text-link" href="tel:+918129422113">Call +91 81294 22113 ↗</a></aside></section>')
pages['contact.html']=('Contact Tripvanda | Plan Your Journey on WhatsApp','Contact Tripvanda on WhatsApp or call +91 81294 22113 for taxi services, flights and train ticket assistance. Send your travel enquiry directly.',intro('LET’S MAKE A PLAN','Your next journey<br>starts with hello.','Tell us where you want to go. We’ll take it from there.')+f'''<section class="wrap section contact-grid"><div><p class="eyebrow">TALK TO TRIPVANDA</p><h2>A real conversation.<br>A better travel plan.</h2><p>Based in Karunagappally, Kollam, Kerala. For travel enquiries and questions about your plans, reach us directly.</p>{button('Chat on WhatsApp')}<a class="contact-phone" href="tel:+918129422113">+91 81294 22113 ↗</a><p class="caption">Messages are answered when our team is available.</p></div><form class="enquiry-form" data-enquiry-form><h2>What are you dreaming of?</h2><label>Your name<input name="name" autocomplete="name" required maxlength="80" placeholder="How should we call you?"></label><label>How can we help?<select name="service"><option>Taxi services</option><option>Flight tickets</option><option>Train tickets</option><option>Other travel enquiry</option></select></label><label>Your travel plans<textarea name="plans" required maxlength="2000" rows="4" placeholder="Destination, dates, passengers, and anything else we should know…"></textarea></label><p class="caption">This opens WhatsApp with your enquiry ready to send. Nothing is submitted to this website.</p><button class="btn primary" type="submit">Continue to WhatsApp ↗</button><p class="form-status" role="status"></p><noscript><p>JavaScript is disabled. Please use the WhatsApp button or call us directly.</p></noscript></form></section>''')
pages['privacy.html']=('Privacy Policy | Tripvanda','Learn how the Tripvanda static website handles travel enquiries and links to WhatsApp.',intro('YOUR INFORMATION','Privacy policy','Last updated: 26 October 2026')+'''<article class="wrap prose"><h2>About this website</h2><p>Tripvanda’s website provides travel information and links to contact our team. It has no accounts, payment checkout, analytics scripts or advertising cookies.</p><h2>Enquiry information</h2><p>Form details are used in your browser to prepare a WhatsApp message. They are not saved by this website. You choose whether to send the message in WhatsApp. Do not enter passport details, identity documents, payment information or other sensitive information in the form.</p><h2>Third-party services</h2><p>The site is intended to be hosted on GitHub Pages. Hosting providers may process technical request data such as IP addresses. Destination images load from Unsplash and fonts load from Google Fonts; these services receive the information needed to deliver those assets. WhatsApp links open a service operated by Meta; information shared there is subject to that service’s policies.</p><h2>Contact and requests</h2><p>To ask about information shared directly with Tripvanda, or request its correction or deletion, call <a href="tel:+918129422113">+91 81294 22113</a>. Information required for a travel arrangement should be discussed directly with our team.</p></article>''')
pages['terms.html']=('Enquiry Terms | Tripvanda','Read Tripvanda website enquiry terms, availability information and guidance before confirming travel arrangements.',intro('TRAVEL WITH CLARITY','Enquiry terms','Last updated: 26 October 2026')+'''<article class="wrap prose"><h2>Information and enquiries</h2><p>This website is an introduction to Tripvanda’s services. Sending a message or completing a form is an enquiry, not a confirmed booking. Destination descriptions are inspiration, not fixed tour itineraries or guaranteed service coverage.</p><h2>Quotes and availability</h2><p>Travel options and fares depend on dates, routes and availability. Confirm the total price, applicable charges, inclusions, exclusions and supplier conditions with our team before proceeding. This website does not collect payments.</p><h2>Changes and cancellations</h2><p>Changes, cancellations and refunds depend on the conditions of the specific arrangement and relevant provider. Ask for those conditions before confirming a service; no general refund promise is made by this website.</p><h2>Traveller details</h2><p>Check names, dates, routes and any relevant travel requirements before confirming. Do not send sensitive documents through this website’s enquiry form.</p><h2>Questions</h2><p>Contact Tripvanda on <a href="tel:+918129422113">+91 81294 22113</a> to discuss a quote or arrangement.</p></article>''')
for file,(title,desc,body) in pages.items():
 active=lambda f:' aria-current="page"' if f==file else ''
 links=''.join(f'<a href="{f}"{active(f)}>{label}</a>' for f,label in nav)
 schema={'@context':'https://schema.org','@graph':[{'@type':'TravelAgency','@id':BASE+'/#organization','name':'Tripvanda','url':BASE+'/','telephone':'+918129422113','logo':BASE+'/assets/brand-mark.webp','description':'Taxi services, flight ticket and train ticket assistance in Karunagappally, Kollam, Kerala.','address':{'@type':'PostalAddress','addressLocality':'Karunagappally','addressRegion':'Kerala','addressCountry':'IN'},'areaServed':{'@type':'Place','name':'Karunagappally, Kollam, Kerala'}},{'@type':'WebSite','@id':BASE+'/#website','url':BASE+'/','name':'Tripvanda','publisher':{'@id':BASE+'/#organization'}},{'@type':'WebPage','@id':BASE+'/'+('' if file=='index.html' else file),'name':title,'description':desc,'isPartOf':{'@id':BASE+'/#website'}}]}
 if file!='index.html': schema['@graph'].append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':BASE+'/'},{'@type':'ListItem','position':2,'name':title.split(' | ')[0],'item':BASE+'/'+file}]})
 canonical=BASE+'/'+('' if file=='index.html' else file)
 content=f'''<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc)}"><meta name="robots" content="index, follow, max-image-preview:large"><meta name="theme-color" content="#083f4a"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="Tripvanda"><meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}/assets/social-card.jpg"><meta property="og:image:alt" content="Tripvanda — Explore. Experience. Together."><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="preconnect" href="https://images.unsplash.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/styles.css"><script src="assets/main.js" defer></script><noscript><style>@media(max-width:850px){{.nav-wrap{{flex-wrap:wrap;padding-block:15px}}.menu-toggle{{display:none}}nav{{display:flex;position:static;flex-wrap:wrap;gap:5px 18px;padding:0;border:0;box-shadow:none}}}}</style></noscript><script type="application/ld+json">{json.dumps(schema)}</script></head><body><a class="skip-link" href="#main">Skip to content</a><div class="topbar">A little inspiration. A whole new journey. <a href="tel:+918129422113">Talk to us: +91 81294 22113 ↗</a></div><header class="header"><div class="nav-wrap wrap"><a class="brand" href="index.html" aria-label="Tripvanda home"><img src="assets/brand-mark.webp" alt="" width="55" height="46"><span>trip<span>vanda</span><small>EXPLORE · EXPERIENCE · TOGETHER</small></span></a><button class="menu-toggle" aria-controls="navigation" aria-expanded="false" aria-label="Open navigation">☰</button><nav id="navigation" aria-label="Main navigation">{links}</nav>{button('Plan a trip',cls='btn nav-cta')}</div></header><main id="main">{body}{cta()}</main><footer><div class="wrap footer-grid"><div><a href="index.html" class="footer-brand">trip<span>vanda</span><span class="brand-dot">.</span></a><p>For the places you’ve dreamed of.<br>And the moments you haven’t imagined yet.</p><span class="footer-tag">EXPLORE · EXPERIENCE · TOGETHER</span></div><div><h2>Explore</h2>{links}</div><div><h2>How we can help</h2><a href="taxi-services.html">Taxi services</a><a href="flight-tickets.html">Flight tickets</a><a href="train-tickets.html">Train tickets</a></div><div><h2>Let’s talk travel</h2><a href="tel:+918129422113">+91 81294 22113</a><a href="{wa('Hi Tripvanda! I have a travel enquiry.')}">Message on WhatsApp ↗</a><p>Karunagappally, Kollam<br>Kerala, India</p></div></div><div class="wrap footer-bottom"><span>© <span data-year>2026</span> Tripvanda. All rights reserved.</span><div><a href="privacy.html">Privacy policy</a><a href="terms.html">Enquiry terms</a><a href="sitemap.xml">Sitemap</a></div></div></footer><a class="floating-whatsapp" href="{wa('Hi Tripvanda! I would like help planning my journey.')}" aria-label="Chat with Tripvanda on WhatsApp"><svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.7" d="M20 11.5a8 8 0 0 1-12 7L3 20l1.5-5A8 8 0 1 1 20 11.5Z"/><path fill="none" stroke="currentColor" stroke-width="1.7" d="M8 7c-2 4 2 8 6 8l2-2-3-1-1 1-2-2 1-1Z"/></svg><span>Let’s talk</span></a></body></html>'''
 (ROOT/file).write_text(content)
(ROOT/'404.html').write_text((ROOT/'contact.html').read_text().replace('<meta name="robots" content="index, follow, max-image-preview:large">','<meta name="robots" content="noindex, follow">').replace('<head>', '<head><base href="/">').replace('https://tripvanda.com/contact.html', 'https://tripvanda.com/404.html').replace('<title>Contact Tripvanda | Plan Your Journey on WhatsApp</title>','<title>Page Not Found | Tripvanda</title>').replace('Your next journey<br>starts with hello.','This path ends here.<br>Your journey doesn’t.').replace(' aria-current="page"', '').replace('Tell us where you want to go. We’ll take it from there.','The page you requested could not be found. Use the navigation to explore, or contact us below.'))
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{BASE}/{"" if f=="index.html" else f}</loc></url>\n' for f in pages)+'</urlset>\n')
print(f'Generated {len(pages)} pages, a 404 page and sitemap.')
